#!/usr/bin/env python3
import json, sys, subprocess

def slack(method, params):
    params = dict(params)
    params['token'] = '<TOKEN>'
    out = subprocess.run(['curl', '-s', '-S', f'https://slack.com/api/{method}', '-d', json.dumps(params)], capture_output=True, text=True)
    try:
        return json.loads(out.stdout)
    except Exception:
        return {'ok': False, 'error': f'bad response: {out.stdout[:500]} {out.stderr[:500]}'}

# 1. Find Priya
users = slack('users.list', {})
if not users.get('ok'):
    print('USERS_ERR', users); sys.exit(1)
matches = []
for u in users['members']:
    real = (u.get('real_name') or '')
    name = (u.get('name') or '')
    if 'priya' in real.lower() or 'priya' in name.lower():
        matches.append(u)
print('MATCHES', json.dumps([{ 'id': u['id'], 'real_name': u.get('real_name'), 'name': u.get('name')} for u in matches], indent=2))
if not matches:
    sys.exit(2)

# 2. Find #launch-plan channel
 chans = slack('conversations.list', {'types': 'public_channel,private_channel', 'limit': 1000})
if not chans.get('ok'):
    print('CHAN_ERR', chans); sys.exit(1)
chan = None
for c in chans['channels']:
    if c.get('name') == 'launch-plan':
        chan = c
        break
print('CHANNEL', chan['id'] if chan else None, chan.get('name') if chan else None)
if not chan:
    sys.exit(3)

# 3. Fetch history around Sep 15 2026 (ET = UTC-4)
# 2026-09-15 00:00:00 ET = 2026-09-15 04:00:00 UTC
import datetime
def ts(s):
    return int(datetime.datetime.fromisoformat(s).timestamp())
oldest = '1757894400'  # 2025? placeholder replaced below
# compute properly
from email.utils import parsedate_to_datetime
def et_to_unix(datestr, time='00:00:00'):
    # America/Indianapolis in Sep is EDT = UTC-4
    dt = datetime.datetime.strptime(datestr + ' ' + time, '%Y-%m-%d %H:%M:%S') - datetime.timedelta(hours=4)
    return str(int(dt.replace(tzinfo=datetime.timezone.utc).timestamp()))

day_start = et_to_unix('2026-09-15', '00:00:00')
day_end = et_to_unix('2026-09-15', '23:59:59')
print('DAY', day_start, day_end)

hist = slack('conversations.history', {'channel': chan['id'], 'oldest': day_start, 'latest': day_end, 'inclusive': 'true', 'limit': 1000})
if not hist.get('ok'):
    print('HIST_ERR', hist); sys.exit(1)
msgs = hist.get('messages', [])
print('MSG_COUNT', len(msgs))
priya_ids = {m['id'] for m in matches}
for m in msgs:
    t = float(m['ts'])
    local = datetime.datetime.fromtimestamp(t, datetime.timezone(datetime.timedelta(hours=-4))).strftime('%Y-%m-%d %H:%M:%S ET')
    sender = m.get('user')
    text = m.get('text', '')
    if sender in priya_ids:
        print('PRIYA_MSG', json.dumps({'ts': m['ts'], 'local': local, 'text': text[:300]}))

